// Foundry VTT Macro: Конструктор заклинаний
// Открывает Конструктор для выделенного токена (или назначенного персонажа игрока).
// ГМ без выделенного токена получает standalone-режим (пресозданные заклинания:
// ручной ранг доктрины, сохранение в мировые предметы).
(() => {
  const actor = canvas.tokens.controlled[0]?.actor || game.user.character || null;
  if (!actor && !game.user.isGM) {
    return ui.notifications.warn(game.i18n.localize("DEDREL.Notifications.SelectToken"));
  }
  game.dedrel.openSpellConstructor(actor);
})();
